// The Supabase 'inventory' table has: id, model, vin, status, days_in_stock,
// price_aed, cost_aed, gross_margin, ... There is no brand/make/year column,
// so build the search query from what actually exists.
// This node runs once for ALL items. It used to read `$json`, which is only the
// FIRST inventory row -- so of twelve units in stock, exactly one (the Land
// Cruiser) was ever priced against the market and the other eleven were never
// scanned at all. The run went green every night regardless, because one item
// in and one item out looks exactly like success.
//
// ── 30 Aug 2026 — THE RUN NEVER FINISHED ────────────────────────────────────
// Fixing the fan-out exposed the next wall. The workflow carries
// executionTimeout: 300 (five minutes). `Apify - Search Competitor Price` had a
// 120 000 ms timeout and retryOnFail with maxTries 2, and `Extract Price with
// AI` a 60 000 ms timeout with maxTries 3 -- and an HTTP node processes its
// items one after another. Worst case that is 240 s + 180 s = 420 s FOR A
// SINGLE UNIT, against a 300 s ceiling for the whole run. Sixteen units in,
// roughly two out, then n8n killed the execution. The filter was never the
// bottleneck; the ceiling was.
//
// Three things now hold the run inside its own ceiling, and they only work
// together:
//   1. per-request budgets were cut (Apify 45 s and no retry, AI 25 s x2), so
//      one unit costs at most ~95 s;
//   2. this node emits at most BATCH_SIZE units, so the run's worst case is
//      BATCH_SIZE * 95 s and is a number somebody can check against the ceiling;
//   3. the workflow ceiling was raised to 1200 s, which is 8 * 95 s plus room.
// Change any one of the three and re-do the arithmetic. A batch that does not
// fit is not slower -- it is silently truncated, which is the bug this replaces.
//
// Coverage is preserved by rotating, not by scanning everything: the schedule
// fires twice a day (05:00 and 17:00 Asia/Dubai) and each run takes the next
// BATCH_SIZE units off a stable ring, so a 16-unit fleet is fully covered every
// 24 hours -- the same daily Apify spend the once-nightly design intended, just
// spread across two executions instead of dying inside one.
const BATCH_SIZE = 8;
const SLOT_HOURS = 12;          // must match the schedule interval

const units = [];
for (const row of $input.all()) {
  const item = row.json;
  const model = String(item.model || '').trim();
  if (!model) continue;   // nothing searchable; do not query 'undefined UAE price'
  // A sold unit cannot be repriced and cannot be undercut. Scraping one spends a
  // scrape slot that a unit still on the lot needed.
  if (String(item.status || '').trim().toLowerCase() === 'sold') continue;
  units.push({
    id: item.id,
    model: model,
    vin: item.vin || null,
    localPrice: Number(item.price_aed) || null,
    daysInStock: Number(item.days_in_stock) || 0,
    searchQuery: model + ' price UAE dealership'
  });
}

if (!units.length) return [];

// Sort by id so the ring is the same on every run regardless of the order
// PostgREST happened to return rows in. Without a stable order the offset below
// rotates over a shuffled list and coverage stops being guaranteed.
units.sort((a, b) => String(a.id).localeCompare(String(b.id)));

const take  = Math.min(BATCH_SIZE, units.length);
const slot  = Math.floor(Date.now() / (SLOT_HOURS * 3600 * 1000));
const start = (slot * BATCH_SIZE) % units.length;

const out = [];
for (let i = 0; i < take; i++) {
  const u = units[(start + i) % units.length];
  out.push({ json: Object.assign({}, u, {
    // Carried so a run can say what it looked at rather than implying it looked
    // at everything. `Delivery Report` and the audit summary read these.
    batchSize:   take,
    batchStart:  start,
    fleetSize:   units.length,
    batchOf:     take + ' of ' + units.length + ' units on the lot, offset ' + start,
  }) });
}
return out;

